(async()=>{
 const req=process.mainModule.require.bind(process.mainModule),path=req('node:path');
 global.__ltReq=name=>req(path.join(process.cwd(),'dist/main',name));
 const service=__ltReq('core/system/provider-quota-service.js').getProviderQuotaService();
 global.__ltProbe=service.probes.get('opencode').inner.native;
 const originalSession=await __ltProbe.reader.read();
 if(!originalSession.session)throw new Error('Saved session unavailable');
 const pairs=header=>new Map(header.split(';').filter(Boolean).map(part=>{const eq=part.indexOf('=');return [part.slice(0,eq).trim(),part.slice(eq+1).trim()]}));
 const originalPairs=pairs(originalSession.session.cookieHeader);
 const authNames=['api-platform_serviceToken','api-platform_slh','api-platform_ph'];
 global.__lt={phase:'baseline',requests:[],notifications:[],minted:null,startedAt:new Date().toISOString()};
 const fs=req('node:fs'),crypto=req('node:crypto');
 const source=path.join(req('node:os').homedir(),'Library/Application Support/harness/mimo-usage-sessions/legacy.bin');
 const isolated=path.join(req('electron').app.getPath('userData'),'mimo-usage-sessions/legacy.bin');
 const digest=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
 const sourceBefore=digest(source),isolatedBefore=digest(isolated);
 const save=__ltProbe.reader.saveRenewed.bind(__ltProbe.reader);
 __ltProbe.reader.saveRenewed=(...args)=>{
   const result=save(...args);
   __lt.persistence={sourceUnchanged:digest(source)===sourceBefore,isolatedBlobChanged:digest(isolated)!==isolatedBefore,rotatedSsoPairs:args[1]?.length??0};
   return result;
 };
 global.__ltFreshRenewer=()=>{
   const renewer=new (__ltReq('core/system/provider-quota/mimo-console-session-renewer.js').MimoConsoleSessionRenewer)();
   const renew=renewer.renew.bind(renewer);
   renewer.renew=async(...args)=>{
     const result=await renew(...args);
     if(__lt.phase==='renew' && result.completed){
       __lt.minted=result.setCookies;
       __lt.renewal={attempted:result.attempted,completed:result.completed,consoleCookieNames:[...result.setCookies.keys()],allAuthCookiesMinted:authNames.every(n=>result.setCookies.has(n)),serviceTokenChanged:result.setCookies.get('api-platform_serviceToken')!==originalPairs.get('api-platform_serviceToken')};
     }
     return result;
   };
   __ltProbe.renewer=renewer;
 };
 __ltFreshRenewer();
 const originalFetch=global.fetch;
 global.__ltOriginalFetch=originalFetch;
 global.fetch=async(input,init)=>{
   const url=new URL(typeof input==='string'?input:input.url);
   const quota=url.hostname==='platform.xiaomimimo.com' && url.pathname.startsWith('/api/v1/tokenPlan/');
   const account=url.hostname==='account.xiaomi.com';
   const phase=__lt.phase;
   let headers=new Headers(init?.headers),policy='production';
   if((quota && phase==='reject') || (account && phase==='reject') || (quota && phase==='renew' && !__lt.minted)){
     headers.delete('Cookie');policy='no-cookies';
   }else if(quota && (phase==='renew' || phase==='persisted')){
     // Delete everything except the actual production overlay returned by SSO
     // and userId (account identity, never an authentication token).
     const supplied=pairs(headers.get('Cookie')??'');
     const retained=[...supplied].filter(([n,v])=>n==='userId' || (__lt.minted?.get(n)===v && authNames.includes(n)));
     headers.set('Cookie',retained.map(([n,v])=>`${n}=${v}`).join('; '));policy='sso-returned-auth-only';
   }else if(quota && phase==='control'){
     const user=pairs(headers.get('Cookie')??'').get('userId');
     headers.delete('Cookie');if(user)headers.set('Cookie',`userId=${user}`);policy='identity-only';
   }
   const sent=pairs(headers.get('Cookie')??'');
   const response=await originalFetch(input,{...init,headers});
   if(quota || account || url.hostname.endsWith('.xiaomimimo.com'))__lt.requests.push({at:new Date().toISOString(),phase,host:url.hostname,path:url.pathname,status:response.status,cookiePolicy:policy,authCookieCount:authNames.filter(n=>sent.has(n)).length,allSentAuthFromSso:authNames.filter(n=>sent.has(n)).every(n=>__lt.minted?.get(n)===sent.get(n)),originalServiceTokenSent:sent.has('api-platform_serviceToken') && sent.get('api-platform_serviceToken')===originalPairs.get('api-platform_serviceToken'),setCookieCount:response.headers.getSetCookie?.().length??0});
   return response;
 };
 __ltReq('notifications/notification-service.js').getNotificationService().subscribe(record=>{if(record.kind==='quota-reauth')__lt.notifications.push({kind:record.kind,title:record.title,delivery:record.delivery,createdAt:record.createdAt})});
 global.__ltNegativeControl=async()=>{
   const session=(await __ltProbe.reader.read()).session;
   if(!session)throw new Error('Persisted session missing');
   __lt.phase='control';
   const statuses=[];
   for(const endpoint of ['usage','detail']){
     const response=await fetch(`https://platform.xiaomimimo.com/api/v1/tokenPlan/${endpoint}?userId=${encodeURIComponent(session.userId)}`,{headers:{Cookie:session.cookieHeader,Accept:'application/json'}});
     statuses.push(response.status);await response.arrayBuffer();
   }
   __lt.phase='persisted';
   return {statuses,onlyIdentityCookieSent:true};
 };
 global.__ltReport=()=>({phase:__lt.phase,startedAt:__lt.startedAt,requests:__lt.requests,notifications:__lt.notifications,renewal:__lt.renewal,persistence:__lt.persistence,sourceStillUnchanged:digest(source)===sourceBefore});
 return {profile:req('electron').app.getPath('userData'),savedSessionAvailable:true,plaintextExported:false,originalSessionNeverModified:true};
})()

(async()=>{
 await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 const settings=await window.electronAPI.getSettings();
 window.__ltOriginalModel=settings.data.defaultModelByProvider;
 const changed=await window.electronAPI.updateSettings({defaultModelByProvider:{...window.__ltOriginalModel,opencode:'xiaomi-token-plan-ams/mimo-v2.6-pro'}});
 const refreshed=await window.electronAPI.quotaRefresh('opencode');
 if(!changed.success || !refreshed.success || !refreshed.data?.ok)throw new Error('Initial live quota unavailable');
 if(!document.querySelector('[data-testid="quota-provider-opencode"]'))document.querySelector('[data-testid="quota-toggle"]').click();
 await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 return {snapshot:refreshed.data,strip:document.querySelector('[data-testid="quota-strip"]').textContent,row:document.querySelector('[data-testid="quota-provider-opencode"]').textContent};
})()

(async()=>{
 const before=(await window.electronAPI.quotaGetProvider('opencode')).data;
 document.querySelector('[data-testid="quota-refresh-opencode"]').click();
 await new Promise(r=>setTimeout(r,8000));
 await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 const after=(await window.electronAPI.quotaGetProvider('opencode')).data;
 return {before,after,strip:document.querySelector('[data-testid="quota-strip"]').textContent,row:document.querySelector('[data-testid="quota-provider-opencode"]').textContent,reauthVisible:!!document.querySelector('[data-testid="quota-reauth-opencode"]'),barCount:document.querySelectorAll('[data-testid="quota-provider-opencode"] .bar').length};
})()

(async()=>{
 const response=await window.electronAPI.updateSettings({defaultModelByProvider:window.__ltOriginalModel});
 const settings=await window.electronAPI.getSettings();
 if(!response.success)throw new Error('Settings restore failed');
 return {restoredModel:settings.data.defaultModelByProvider};
})()

import fs from 'node:fs';
const [target,file,name]=process.argv.slice(2);
const port=target==='main'?9823:9822;
const list=await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page=list.find(t=>target==='main'?t.type==='node':t.type==='page'&&t.url.startsWith('http://localhost:4579'));
if(!page)throw new Error('Expected isolated debug target missing');
const ws=new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
let id=0;const calls=new Map();
ws.onmessage=event=>{const msg=JSON.parse(event.data);if(calls.has(msg.id)){const {resolve,reject}=calls.get(msg.id);calls.delete(msg.id);msg.error?reject(new Error(msg.error.message)):resolve(msg.result)}};
function call(method,params={}){return new Promise((resolve,reject)=>{const n=++id;calls.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}))})}
try{
 let focus;
 if(target!=='main'){
   await call('Emulation.setFocusEmulationEnabled',{enabled:true});
   try{await call('Emulation.setPageVisibilityOverride',{visibility:'visible'})}catch{}
   const state=await call('Runtime.evaluate',{expression:'({hidden:document.hidden,visibility:document.visibilityState})',returnByValue:true});
   focus=state.result.value;
   if(focus.hidden || focus.visibility!=='visible')throw new Error('Focus emulation not effective');
 }
 const result=await call('Runtime.evaluate',{expression:fs.readFileSync(file,'utf8'),awaitPromise:true,returnByValue:true});
 if(result.exceptionDetails)throw new Error('Evaluation failed; remote exception was withheld to avoid exporting sensitive runtime data');
 const receipt={at:new Date().toISOString(),...(focus?{focus}:{}),result:result.result.value};
 const output=`docs/plans/2026-09-25-mimo-session-resilience_evidence/2026-10-27-review-fixes/${name}.json`;
 fs.writeFileSync(output,JSON.stringify(receipt,null,2)+'\n');
 console.log(`${name}: captured successfully`);
}finally{ws.close()}

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve('dist/renderer/browser');
const types = {'.html':'text/html','.js':'application/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.woff2':'font/woff2'};
http.createServer((req,res)=>{
  const file = path.resolve(root, '.'+decodeURIComponent(new URL(req.url,'http://localhost').pathname));
  if(file!==root && !file.startsWith(root+path.sep)){ res.writeHead(403).end();return; }
  let target = file;
  if(!fs.existsSync(target) || fs.statSync(target).isDirectory()) target=path.join(root,'index.html');
  res.writeHead(200,{'Content-Type':types[path.extname(target)] || 'application/octet-stream'});
  fs.createReadStream(target).pipe(res);
}).listen(4579,'127.0.0.1');
